using System;
using System.Collections.Generic;
using System.Diagnostics;
using System.Drawing;
using System.IO;
using System.IO.Compression;
using System.Linq;
using System.Reflection;
using System.Threading;
using System.Windows.Forms;
using AlpineQuestPort;
class WorkspaceToolsTests {
    static readonly BindingFlags Flags=BindingFlags.Instance|BindingFlags.NonPublic;
    static T Field<T>(object o,string n){return (T)o.GetType().GetField(n,Flags).GetValue(o);}
    static object Call(object o,string n,params object[] args){return o.GetType().GetMethod(n,Flags).Invoke(o,args);}
    static void Check(bool ok,string text){if(!ok)throw new Exception(text);Console.WriteLine("PASS: "+text);}
    static void Pump(int ms){var stop=DateTime.UtcNow.AddMilliseconds(ms);while(DateTime.UtcNow<stop){Application.DoEvents();Thread.Sleep(10);}}
    static void Tile(string root,int z,int x,int y,Color color){string path=Path.Combine(root,z.ToString(),x.ToString(),y+".png");Directory.CreateDirectory(Path.GetDirectoryName(path));using(var b=new Bitmap(256,256)){using(var g=Graphics.FromImage(b))g.Clear(color);b.Save(path);}File.WriteAllText(path+".meta","0\n\n");File.SetLastWriteTimeUtc(path,DateTime.UtcNow.AddDays(-4));}
    static void Shot(Form f,string path){using(var b=new Bitmap(f.Width,f.Height)){f.DrawToBitmap(b,new Rectangle(Point.Empty,f.Size));b.Save(path);}}
    static MapDocument Document(){var d=new MapDocument();d.Waypoints.Add(new GeoPoint(0,0){Name="Point",Group="Group"});d.Waypoints[0].Radio.HeightA=37;return d;}
    static void Backups(string output){string folder=Path.Combine(output,"original");Directory.CreateDirectory(folder);var d=Document();new ViewSettings{SidebarCollapsed=true}.Save(Path.Combine(folder,"view-settings.xml"));FavoriteSources.Save(Path.Combine(folder,"favorites.xml"),MapSource.BuiltIn().Take(2).ToList());File.WriteAllText(Path.Combine(folder,"group-visibility.xml"),"<groups><hidden>Group</hidden></groups>");Tile(Path.Combine(folder,"tile-cache-v2",MapSource.BuiltIn()[0].CacheKey),2,2,2,Color.Red);Tile(Path.Combine(folder,"elevation-cache"),14,8192,8192,Color.FromArgb(128,100,0));var capture=WorkspaceArchive.Capture(folder,DocumentSnapshot.Capture(d));string path=Path.Combine(output,"all.mapdesk");WorkspaceArchive.Export(path,folder,capture,true);string restored=WorkspaceArchive.Restore(path,Path.Combine(output,"restored"));Check(MapFiles.Load(Path.Combine(restored,"workspace.gpx")).Waypoints[0].Radio.HeightA==37,"backup restores point and radio properties");Check(ViewSettings.Load(Path.Combine(restored,"view-settings.xml")).SidebarCollapsed&&FavoriteSources.Load(Path.Combine(restored,"favorites.xml")).Count==2,"backup restores settings and favorites");Check(File.Exists(Path.Combine(restored,"elevation-cache","14","8192","8192.png"))&&Directory.Exists(Path.Combine(restored,"tile-cache-v2")),"backup includes DEM and map caches");WorkspaceArchive.Export(path,folder,capture,false);string light=WorkspaceArchive.Restore(path,Path.Combine(output,"restored"));Check(!Directory.Exists(Path.Combine(light,"elevation-cache"))&&!Directory.Exists(Path.Combine(light,"tile-cache-v2"))&&light!=restored,"optional cache exclusion and separate restore folders");
        string bad=Path.Combine(output,"bad.mapdesk");using(var stream=File.Create(bad))using(var zip=new ZipArchive(stream,ZipArchiveMode.Create)){using(var w=new StreamWriter(zip.CreateEntry("../escape.txt").Open()))w.Write("bad");}bool rejected=false;try{WorkspaceArchive.Restore(bad,Path.Combine(output,"restored"));}catch(InvalidDataException){rejected=true;}Check(rejected&&!File.Exists(Path.Combine(output,"escape.txt")),"restore rejects path traversal");
        using(var stream=File.Open(path,FileMode.Open))using(var zip=new ZipArchive(stream,ZipArchiveMode.Update)){zip.GetEntry("workspace.gpx").Delete();using(var w=new StreamWriter(zip.CreateEntry("workspace.gpx").Open()))w.Write("corrupt");}rejected=false;try{WorkspaceArchive.Restore(path,Path.Combine(output,"restored"));}catch(InvalidDataException){rejected=true;}Check(rejected&&Directory.GetDirectories(Path.Combine(output,"restored"),"*.partial").Length==0,"corrupt archive rejected and staging removed");Check(File.Exists(Path.Combine(restored,"workspace.gpx")),"failed restore leaves earlier workspace intact");
    }
    static void Heights(string output){string cache=Path.Combine(output,"dem");Tile(cache,12,2048,2048,Color.FromArgb(128,100,0));using(var elevation=new ElevationStore(cache)){double? value=null;var stop=DateTime.UtcNow.AddSeconds(3);while(!value.HasValue&&DateTime.UtcNow<stop){value=elevation.AtAvailable(new GeoPoint(0,0),14);Thread.Sleep(15);}Check(value==100&&elevation.LastSampleZoom==12,"HUD uses four-day-old offline DEM at available scale");Check(!elevation.At(new GeoPoint(0,0),14).HasValue,"precise profile does not silently substitute coarse DEM");}Tile(cache,14,8192,8192,Color.FromArgb(128,120,0));using(var elevation=new ElevationStore(cache)){double? value=null;var stop=DateTime.UtcNow.AddSeconds(3);while(!value.HasValue&&DateTime.UtcNow<stop){value=elevation.At(new GeoPoint(0,0),14);Thread.Sleep(15);}Check(value==120,"exact DEM survives store restart and old modification time");}}
    static void Language(string output){var all=MapSource.BuiltIn();var hybrid=all.First(s=>s.Id=="google-hybrid");var russian=hybrid.Copy();russian.Language="ru";var records=new List<CachedFragment>{new CachedFragment{Source=russian.CacheKey,Z=14,X=1,Y=1}};Check(CachedSourceVariants.Find(all,records,hybrid).Any(s=>s.CacheKey==russian.CacheKey),"cached Russian hybrid discoverable from local-language source");var esri=all[0];var alias=esri.Copy();alias.Language="ru";string root=Path.Combine(output,"aliases");Tile(Path.Combine(root,alias.CacheKey),2,2,2,Color.Red);using(var store=new TileStore(Path.Combine(root,esri.CacheKey),null,esri)){Image image=null;var stop=DateTime.UtcNow.AddSeconds(3);while(image==null&&DateTime.UtcNow<stop){image=store.GetTile(2,2,2);Thread.Sleep(15);}using(image)Check(image!=null,"language-independent source reuses legacy language cache");}
        using(var dialog=new MapsDialog(all,russian,delegate{})){dialog.Show();Pump(50);var list=Field<ListBox>(dialog,"list");Check(((MapSource)list.SelectedItem).Id==russian.Id,"catalog selects copied current source rather than first entry");list.SelectedItem=all.First(s=>s.Id=="google-roads-ru");Check(((string)Field<ComboBox>(dialog,"language").SelectedItem).StartsWith("ru "),"source selection restores its configured language");dialog.Close();}
    }
    static void UI(string output){string folder=Path.Combine(output,"ui");using(var form=new MainForm(null,true,folder)){form.Show();Pump(100);var map=Field<MapCanvas>(form,"map");map.Settings.Gpu=false;var current=Field<MapSource>(form,"currentSource");var source=current.Copy();source.Name="Coverage test";var tiles=new List<CachedFragment>{new CachedFragment{Source=source.CacheKey,Z=4,X=8,Y=8},new CachedFragment{Source=source.CacheKey,Z=4,X=9,Y=8}};Call(form,"ShowCoverage",source,tiles,4);Check(map.ShowCoverage&&!map.Tiles.OnlineEnabled&&map.CoverageLevel==4,"geographic coverage enters offline preview");Shot(form,Path.Combine(output,"coverage-map.png"));form.ApplyPreset("Измерения");Check(map.Settings.RangeRings&&!map.Settings.Perspective,"measurement preset applied");form.ApplyPreset("Обзор");Check(!map.Settings.RangeRings&&!map.Settings.PointNames,"overview preset applied");form.ApplyPreset("Профиль");Check(map.Settings.Elevation,"profile preset enables elevations");
            Tile(Path.Combine(folder,"elevation-cache"),14,8192,8192,Color.FromArgb(128,100,0));using(var dialog=new MapCacheDialog(Path.Combine(folder,"tile-cache-v2"),MapSource.BuiltIn(),current,0)){dialog.Show();Pump(300);Check(Field<ComboBox>(dialog,"source").Items.Cast<MapSource>().Any(s=>s.Id=="terrain-dem"),"DEM present in offline coverage inventory");Field<ComboBox>(dialog,"source").SelectedItem=Field<ComboBox>(dialog,"source").Items.Cast<MapSource>().First(s=>s.Id=="terrain-dem");Shot(dialog,Path.Combine(output,"dem-cache.png"));dialog.Close();}
            Call(form,"SavePreferences");Check(File.ReadAllText(Path.Combine(folder,"preferences.xml")).Contains("<zoom>"),"view position saved with source");form.Close();Pump(1000);}
        using(var dialog=new BackupOptionsDialog()){dialog.Show();Pump(50);Shot(dialog,Path.Combine(output,"backup-options.png"));dialog.Close();}
    }
    static void ViewPersistence(string output){string folder=Path.Combine(output,"persist");using(var form=new MainForm(null,false,folder)){form.Show();Pump(150);var hybrid=MapSource.BuiltIn().First(s=>s.Id=="google-hybrid");hybrid.Language="ru";Call(form,"SetSource",hybrid);var xml=System.Xml.Linq.XElement.Load(Path.Combine(folder,"preferences.xml"));Check((string)xml.Element("language")=="ru"&&(string)xml.Element("map")=="google-hybrid","selected source and language persist before window closes");var map=Field<MapCanvas>(form,"map");map.GoTo(new GeoPoint(10,15),13);Pump(1800);xml=System.Xml.Linq.XElement.Load(Path.Combine(folder,"preferences.xml"));Check(Math.Abs((double)xml.Element("lat")-10)<.000001&&(int)xml.Element("zoom")==13,"idle view position persists without closing");form.Close();Pump(1000);}using(var form=new MainForm(null,false,folder)){form.Show();Pump(100);var map=Field<MapCanvas>(form,"map");Check(Field<MapSource>(form,"currentSource").Language=="ru"&&Math.Abs(map.Center.Lon-15)<.000001&&map.Zoom==13,"restart restores exact source variant and view");form.Close();Pump(1000);}}
    static void RealDiagnostics(string folder,string output){var demFiles=WorkspaceArchive.SafeFiles(Path.Combine(folder,"elevation-cache")).Where(p=>p.EndsWith(".png",StringComparison.OrdinalIgnoreCase)).ToList();int valid=0,invalid=0;foreach(var file in demFiles)try{using(var image=new Bitmap(file))if(image.Width==256&&image.Height==256)valid++;else invalid++;}catch{invalid++;}Console.WriteLine("REAL DEM files valid="+valid+" invalid="+invalid);var document=MapFiles.Load(Path.Combine(folder,"workspace.gpx"));Console.WriteLine("REAL objects points="+document.Waypoints.Count+" tracks="+document.Tracks.Count+" zones="+document.Zones.Count);
        var source=MapSource.BuiltIn().First(s=>s.Id=="google-hybrid");source.Language="ru";using(var store=new TileStore(Path.Combine(folder,"tile-cache-v2",source.CacheKey),null,source))using(var map=new MapCanvas(store){Size=new Size(1280,720)})using(var bitmap=new Bitmap(1280,720))using(var g=Graphics.FromImage(bitmap)){map.Document=document;map.Settings.RangeRings=false;map.Settings.Gpu=true;map.Settings.DataCards=false;map.Settings.Elevation=false;map.Fit();if(document.Waypoints.Count>0)map.GoTo(document.Waypoints[0],14);var paint=typeof(MapCanvas).GetMethod("OnPaint",Flags);var samples=new List<double>();for(int i=0;i<25;i++){map.Pan(2,1);var watch=Stopwatch.StartNew();paint.Invoke(map,new object[]{new PaintEventArgs(g,map.ClientRectangle)});if(i>=5)samples.Add(watch.Elapsed.TotalMilliseconds);Thread.Sleep(10);}samples.Sort();Console.WriteLine("REAL offline raster+objects paint median="+samples[samples.Count/2].ToString("F2")+" ms; backend="+map.RenderBackend);}
    }
    [STAThread]static int Main(string[] args){try{Application.EnableVisualStyles();string output=Path.GetFullPath(args[0]);Directory.CreateDirectory(output);Backups(output);Heights(output);Language(output);UI(output);ViewPersistence(output);if(args.Length>1)RealDiagnostics(args[1],output);Console.WriteLine("PASS: workspace tools complete");return 0;}catch(Exception ex){Console.WriteLine(ex);return 1;}}
}
